import{_ as s,a,c as t,ac as o}from"./chunks/framework.BSuaGltH.js";const u=JSON.parse('{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课","description":"L73–L96 原创练习和答案解析。","frontmatter":{"title":"第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课","description":"L73–L96 原创练习和答案解析。","splitFrom":"life/english/new-concept/book-2/unit-04/review.md","showdocs":{"topics":[{"id":"english","title":"英语","link":"/topics/english/"}],"kind":"读写与对话练习","scope":"general","audience":"general","group":"学习与记录","seriesTitle":"第二册：实践与进步 · 单元 4 复习与自测","summary":"L73–L96 原创练习和答案解析。","status":"active","related":[{"title":"程序员英语 01：学习路线与能力自测","link":"/life/english/programmer/overview","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 02：技术词汇与句子骨架","link":"/life/english/programmer/vocabulary","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 03：读懂文档中的条件与约束","link":"/life/english/programmer/reading-docs","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 04：读报错、搜索与求助","link":"/life/english/programmer/errors-search","kind":"路线与能力起点","scope":"general","audience":"general"},{"title":"程序员英语 05：写 Issue、Commit 与 PR","link":"/life/english/programmer/issue-pr","kind":"路线与能力起点","scope":"general","audience":"general"}],"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","link":"/life/english/new-concept/book-2/unit-04/review-part-02"},"next":false},"layout":"ReadingPage","sidebar":false,"aside":false,"prev":{"text":"第二册：实践与进步 · 单元 4 复习与自测 · 第81–89课","link":"/life/english/new-concept/book-2/unit-04/review-part-02"},"next":false},"headers":[],"relativePath":"life/english/new-concept/book-2/unit-04/review-part-03.md","filePath":"life/english/new-concept/book-2/unit-04/review-part-03.md"}'),n={name:"life/english/new-concept/book-2/unit-04/review-part-03.md"};function r(i,e,l,d,h,p){return a(),t("div",null,[...e[0]||(e[0]=[o('<h1 id="第二册-实践与进步-·-单元-4-复习与自测-·-第90–96课" tabindex="-1">第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课 <a class="header-anchor" href="#第二册-实践与进步-·-单元-4-复习与自测-·-第90–96课" aria-label="Permalink to &quot;第二册：实践与进步 · 单元 4 复习与自测 · 第90–96课&quot;">​</a></h1><p><a href="/life/english/new-concept/book-2/unit-04/review">返回分篇目录</a></p><p><a href="/life/english/new-concept/book-2/unit-04/overview">单元导读</a> · <a href="/life/english/new-concept/book-2/unit-04/grammar">单元语法总结</a> · <a href="/life/english/new-concept/book-2/unit-04/vocabulary">单元单词与短语</a> · <a href="/life/english/new-concept/book-2/unit-04/review">单元复习与自测</a></p><p>先独立作答，再展开答案。下列原创题从相应课时选取，覆盖本范围每一课；错题请回到课时讲解解释错误原因，再替换一个条件重做。</p><h2 id="lesson-90-·-分词修饰与逻辑主语" tabindex="-1">Lesson 90 · 分词修饰与逻辑主语 <a class="header-anchor" href="#lesson-90-·-分词修饰与逻辑主语" aria-label="Permalink to &quot;Lesson 90 · 分词修饰与逻辑主语 {#lesson-90-·-分词修饰与逻辑主语}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The potatoes fried this morning were used for supper.</p><h3 id="练习-1-17" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-17" aria-label="Permalink to &quot;练习 1 {#练习-1-17}&quot;">​</a></h3><p>主句谓语是 fried 还是 were used？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> were used</p><p><strong>解析：</strong> fried this morning 修饰 potatoes，were used 完成主句断言。</p></details><p><strong>表达迁移：</strong> 写三句临时菜单调整，说明已有食材、用完的食材和新的搭配。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The potatoes fried this morning were used for supper. The cook added vegetables and a fresh sauce. There was no fish left in the kitchen.</p><p>第一句的组织方式：fried this morning 是过去分词后置定语，were used 才是主句谓语，主语 potatoes 为复数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：We ran out potatoes 缺 of；Potatoes ran out 是另一种主语安排。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-090">回看本课</a></p><h2 id="lesson-91-·-过去进行时与叙事背景" tabindex="-1">Lesson 91 · 过去进行时与叙事背景 <a class="header-anchor" href="#lesson-91-·-过去进行时与叙事背景" aria-label="Permalink to &quot;Lesson 91 · 过去进行时与叙事背景 {#lesson-91-·-过去进行时与叙事背景}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> We were drifting over the fields when the pilot noticed a clear landing area.</p><h3 id="练习-1-18" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-18" aria-label="Permalink to &quot;练习 1 {#练习-1-18}&quot;">​</a></h3><p>填 drift：We were ___ over the fields.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> drifting</p><p><strong>解析：</strong> 过去进行时为 were 加 -ing。</p></details><p><strong>表达迁移：</strong> 写三句空中观景或登高经历，包含背景、发现与最终位置。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>We were drifting over the fields when the pilot noticed a clear landing area. He checked the wind once more. We landed beyond a fence, well away from the road.</p><p>第一句的组织方式：were drifting 为背景，when 引出 noticed；a clear landing area 首次引入新地点。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：over the fields 是在田野上方；through the fields 通常表示从田地内部穿行。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-091">回看本课</a></p><h2 id="lesson-92-·-间接引语与视角转换" tabindex="-1">Lesson 92 · 间接引语与视角转换 <a class="header-anchor" href="#lesson-92-·-间接引语与视角转换" aria-label="Permalink to &quot;Lesson 92 · 间接引语与视角转换 {#lesson-92-·-间接引语与视角转换}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> I do not think the receptionist meant to be rude.</p><h3 id="练习-1-19" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-19" aria-label="Permalink to &quot;练习 1 {#练习-1-19}&quot;">​</a></h3><p>选 rude/rudely：She did not mean to be ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> rude</p><p><strong>解析：</strong> be 后用形容词作表语。</p></details><p><strong>表达迁移：</strong> 写一次误会的处理，分开描述听到的语气、可能原因和自己的行动。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>I do not think the receptionist meant to be rude. Her reply sounded sharp because the room was noisy. I repeated my question calmly and she helped me.</p><p>第一句的组织方式：do not think 否定判断，meant to be 表意图；说话者评价的是意图，而不是否认语气可能让人不舒服。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：rude 是形容词，rudely 是副词；meant to be 后用 rude，不是 rudely。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-092">回看本课</a></p><h2 id="lesson-93-·-定语从句与指代" tabindex="-1">Lesson 93 · 定语从句与指代 <a class="header-anchor" href="#lesson-93-·-定语从句与指代" aria-label="Permalink to &quot;Lesson 93 · 定语从句与指代 {#lesson-93-·-定语从句与指代}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The statue, which was donated by local artists, stands beside the library.</p><h3 id="练习-1-20" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-20" aria-label="Permalink to &quot;练习 1 {#练习-1-20}&quot;">​</a></h3><p>填 which/that：The statue, ___ was donated last year, stands here.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> which</p><p><strong>解析：</strong> 逗号引出的非限制性从句用 which。</p></details><p><strong>表达迁移：</strong> 为一件虚构公共礼物写介绍，交代来源、所在位置和象征意义。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The statue, which was donated by local artists, stands beside the library. Students designed the garden around it. A plaque explains the donors&#39; wish for friendship.</p><p>第一句的组织方式：The statue 为主语，stands 为主句谓语；逗号内 which was donated 是非限制性定语从句，which 指 statue。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：非限制性从句通常不能用 that 替代 which，也不能省略关系代词。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-093">回看本课</a></p><h2 id="lesson-94-·-一般现在时与习惯" tabindex="-1">Lesson 94 · 一般现在时与习惯 <a class="header-anchor" href="#lesson-94-·-一般现在时与习惯" aria-label="Permalink to &quot;Lesson 94 · 一般现在时与习惯 {#lesson-94-·-一般现在时与习惯}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The children practise floating before they learn to swim across the pool.</p><h3 id="练习-1-21" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-21" aria-label="Permalink to &quot;练习 1 {#练习-1-21}&quot;">​</a></h3><p>填 float：The children practise ___.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> floating</p><p><strong>解析：</strong> practise 通常接动名词。</p></details><p><strong>表达迁移：</strong> 写一项技能的三阶段学习计划，明确监督条件与进入下一阶段的标准。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The children practise floating before they learn to swim across the pool. A coach stays within reach. Each child moves to the next task only when ready.</p><p>第一句的组织方式：practise 后接动名词 floating，learn 后接 to swim；before 引出学习顺序，children 为复数。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：practise to float 应改为 practise floating；learn floating 并非此处常用搭配。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-094">回看本课</a></p><h2 id="lesson-95-·-非真实条件句" tabindex="-1">Lesson 95 · 非真实条件句 <a class="header-anchor" href="#lesson-95-·-非真实条件句" aria-label="Permalink to &quot;Lesson 95 · 非真实条件句 {#lesson-95-·-非真实条件句}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> If people could store sunlight in a pocket, winter evenings would look different.</p><h3 id="练习-1-22" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-22" aria-label="Permalink to &quot;练习 1 {#练习-1-22}&quot;">​</a></h3><p>选 would/could：If people ___ store sunlight, nights would change.</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> could</p><p><strong>解析：</strong> if 从句的能力假设用 could。</p></details><p><strong>表达迁移：</strong> 创造一项虚构能力，写一个好处、一个限制和一次选择，明确这是故事设定。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>If people could store sunlight in a pocket, winter evenings would look different. In my story, each lamp holds one hour of daylight. The characters must decide when to use it.</p><p>第一句的组织方式：could store 表非真实能力假设，would look 表设想结果；sunlight 不可数，in a pocket 为幻想中的容器。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：would can store 错误；能力假设直接用 could，结果可用 would be able to。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-095">回看本课</a></p><h2 id="lesson-96-·-被动语态与信息重点" tabindex="-1">Lesson 96 · 被动语态与信息重点 <a class="header-anchor" href="#lesson-96-·-被动语态与信息重点" aria-label="Permalink to &quot;Lesson 96 · 被动语态与信息重点 {#lesson-96-·-被动语态与信息重点}&quot;">​</a></h2><p><strong>阅读材料（本站原创）：</strong> The lanterns are placed by the river to honour family ancestors.</p><h3 id="练习-1-23" tabindex="-1">练习 1 <a class="header-anchor" href="#练习-1-23" aria-label="Permalink to &quot;练习 1 {#练习-1-23}&quot;">​</a></h3><p>by the river 在例句中表示执行者还是地点？</p><details class="details custom-block"><summary>参考答案与解析</summary><p><strong>答案：</strong> 地点。</p><p><strong>解析：</strong> river 不是摆灯动作的执行者，by 在此意为在旁边。</p></details><p><strong>表达迁移：</strong> 介绍一个真实或虚构纪念习俗，标明来源，分别写行动、意义和收尾安排。</p><details class="details custom-block"><summary>表达参考与点评</summary><p>The lanterns are placed by the river to honour family ancestors. In this fictional village, families tell stories about older generations. They collect the lanterns afterwards to keep the river clean.</p><p>第一句的组织方式：are placed 是一般现在时被动，概括仪式做法；by the river 是地点而非执行者，to honour 表目的。其后的两句补充本课情境中的具体发展，作答时应保持人物和时间指代一致。重点自查：by 不总是被动执行者：by the river 表在河边，不是河流摆放灯笼。</p></details><p><a href="/life/english/new-concept/book-2/unit-04/lesson-096">回看本课</a></p>',60)])])}const g=s(n,[["render",r]]);export{u as __pageData,g as default};
